// Data Dummy: simulasi data kandidat (Run Once for All Items)
const candidates = [
  {
    candidate_name: "Andi Pratama",
    position: "Network Engineer",
    claimed_skills: ["MikroTik RouterOS", "OSPF", "BGP", "VLAN", "Wireshark"],
    past_company_type: "ISP skala menengah"
  },
  {
    candidate_name: "Siti Rahma",
    position: "Network Security Analyst",
    claimed_skills: ["Firewall", "IDS/IPS", "Incident Response", "SIEM", "Linux Hardening"],
    past_company_type: "Startup e-commerce"
  }
];

return candidates.map(c => ({ json: c }));

// Prompt Builder: menyusun System Prompt + User Prompt dari profil kandidat
const c = $input.item.json;
const skills = Array.isArray(c.claimed_skills) ? c.claimed_skills.join(", ") : c.claimed_skills;

const system_prompt = [
  "You are a Senior Technical Interviewer with more than 10 years of hands-on experience.",
  "Your task is to create exactly ONE technical case-study question (troubleshooting scenario) for a job candidate.",
  "Rules:",
  "1. The scenario must be realistic and based on the candidate's claimed skills.",
  "2. Compare the claimed skills with the type of company where the candidate previously worked, then probe the depth of their real experience.",
  "3. The question must require step-by-step technical reasoning, not a definition or a yes/no answer.",
  "4. Write the output in Bahasa Indonesia.",
  "5. Output format:",
  "Topik: <short topic>",
  "Pertanyaan: <the case-study question>",
  "6. Do not add any greeting, explanation, or answer key."
].join("\n");

const user_prompt = [
  "Candidate Name: " + c.candidate_name,
  "Position Applied: " + c.position,
  "Claimed Skills: " + skills,
  "Past Company Type: " + c.past_company_type,
  "",
  "Generate one technical case-study question for this candidate."
].join("\n");

return {
  json: {
    candidate_name: c.candidate_name,
    position: c.position,
    claimed_skills: c.claimed_skills,
    past_company_type: c.past_company_type,
    system_prompt,
    user_prompt
  }
};

