// Mock Jawaban: mensimulasikan jawaban kandidat (teknis vs generik) dengan if-else
const base = $('Prompt Builder').item.json;
const question = $('Generate Pertanyaan').item.json.text;

let answer;
if (base.candidate_name === "Andi Pratama") {
  // Skenario 1: jawaban teknis & mendalam (menyebut command, filter, TTL, solusi)
  answer =
    "Karena loss hanya pada blok IP via Upstream A, saya fokus ke jalur dan BGP Upstream A. " +
    "Cek session BGP dengan /routing bgp session print (RouterOS v6: /routing bgp peer print status): state Established, uptime, prefix count; uptime pendek berarti flapping, lalu /log print where topics~bgp untuk alasan reset (misalnya hold timer expired). " +
    "Cek /ip route print where dst-address=<blok IP> untuk melihat apakah best path berpindah antara Upstream A dan B. " +
    "OSPF: /routing ospf neighbor print (state Full, MTU mismatch, dead timer) dan /interface print stats untuk error counter di VLAN 200. " +
    "Dari PC pelanggan saya traceroute berulang; hop acak dan TTL yang berfluktuasi menandakan routing loop atau asymmetric routing. " +
    "Dengan Wireshark atau /tool sniffer di interface Upstream A saya pakai filter icmp.type == 11, tcp.analysis.retransmission, dan bgp, serta membandingkan ip.ttl antar paket. " +
    "Solusi: perbaiki MTU atau link yang bermasalah, atur BGP timer dan route-flap dampening, pakai local-pref atau AS-path prepend agar trafik konsisten lewat satu upstream, rapikan route filter dan redistribusi BGP-OSPF agar tidak loop, lalu verifikasi dengan traceroute, pantau 24 jam, dan dokumentasikan sebagai post-mortem.";
} else {
  // Skenario 2: jawaban generik & dangkal
  answer = "Saya akan memeriksa masalahnya dulu, lalu restart perangkat dan cek kabel. " +
    "Kalau belum bisa, saya tanya rekan tim atau cari solusinya di internet. " +
    "Intinya saya akan berusaha semaksimal mungkin dan bekerja dengan teliti.";
}

return {
  json: {
    candidate_name: base.candidate_name,
    position: base.position,
    claimed_skills: base.claimed_skills,
    past_company_type: base.past_company_type,
    question,
    answer
  }
};

// Evaluator: menyusun prompt penilaian (skor 0-100, analisa, keputusan)
const d = $input.item.json;

const system_prompt = [
  "ROLE: You are a Senior Hiring Manager evaluating a technical interview answer.",
  "Evaluate objectively using this rubric:",
  "- If the answer shows deep troubleshooting steps, specific tools or commands, a logical order of investigation, and root-cause thinking, give a HIGH score (75-100).",
  "- If the answer is partially technical but misses important steps or details, give a MEDIUM score (50-74).",
  "- If the answer is generic, vague, only says restart or ask someone or search the internet, with no technical detail, give a LOW score (0-49).",
  "The pass mark is 70.",
  "Write the output in Bahasa Indonesia, using EXACTLY this format and nothing else:",
  "🎯 Skor: <number 0-100>/100",
  "💡 Analisa: <short analysis, maximum 3 sentences>",
  "🔬 Kedalaman: <Teknis atau Umum>",
  "🚩 Keputusan: <LULUS atau TIDAK LULUS>"
].join("\n");

const user_prompt = [
  "Position: " + d.position,
  "Question Given:",
  d.question,
  "",
  "Candidate Answer:",
  d.answer,
  "",
  "Evaluate the answer now."
].join("\n");

return {
  json: {
    candidate_name: d.candidate_name,
    position: d.position,
    question: d.question,
    answer: d.answer,
    system_prompt,
    user_prompt
  }
};

